export function normalizeInterestingTodayCatalog(records = DEFAULT_INTERESTING_TODAY_CATALOG, { useDefaultWhenEmpty = true } = {}) {
  const source = Array.isArray(records) && (records.length || !useDefaultWhenEmpty)
    ? records
    : DEFAULT_INTERESTING_TODAY_CATALOG;
  const seenIds = new Set();
  const seenHashes = new Set();
  return source
    .map(record => normalizeInterestingTodayRecord(record))
    .filter(record => {
      if (!record || seenIds.has(record.id) || seenHashes.has(record.normalizedHash)) {
        return false;
      }
      seenIds.add(record.id);
      seenHashes.add(record.normalizedHash);
      return true;
    })
    .sort((first, second) => first.month - second.month
      || first.day - second.day
      || second.significance - first.significance
      || first.id.localeCompare(second.id));
}

export function cloneInterestingTodayCatalog(records = []) {
  return (Array.isArray(records) ? records : [])
    .filter(isPlainObject)
    .map(record => ({
      ...record,
      countryCodes: [...record.countryCodes],
      themeCodes: [...record.themeCodes],
      sources: record.sources.map(source => ({ ...source })),
    }));
}

export function normalizeInterestingTodayPreferences(preferences, { accountId = "", fallbackCountryCode = INTERESTING_TODAY_DEFAULT_COUNTRY, checkedAt = null } = {}) {
  const source = isPlainObject(preferences) ? preferences : {};
  const fallbackCountry = normalizeInterestingCountryCode(source.countryCode || fallbackCountryCode) || INTERESTING_TODAY_DEFAULT_COUNTRY;
  return {
    accountId: String(source.accountId || accountId || "").trim(),
    countryCode: fallbackCountry,
    language: source.language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : INTERESTING_TODAY_LANGUAGE,
    showEvents: source.showEvents !== false,
    showPeople: source.showPeople !== false,
    updatedAt: normalizeTimestamp(source.updatedAt) || normalizeTimestamp(checkedAt),
  };
}

export function validateInterestingTodayPreferences(preferences, options = {}) {
  const normalized = normalizeInterestingTodayPreferences(preferences, options);
  if (!normalized.showEvents && !normalized.showPeople) {
    return {
      ok: false,
      error: "interesting_today_all_sections_hidden",
      preferences: normalized,
    };
  }

  return {
    ok: true,
    preferences: normalized,
  };
}

export function normalizeInterestingTodaySet(set) {
  if (!isPlainObject(set)) {
    return null;
  }

  const countryCode = normalizeInterestingCountryCode(set.countryCode);
  const language = set.language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : "";
  const localDate = normalizeLocalDate(set.localDate);
  if (!countryCode || !language || !localDate) {
    return null;
  }

  return {
    id: sanitizeInterestingId(set.id) || createInterestingTodaySetKey({ countryCode, language, localDate }),
    countryCode,
    language,
    localDate,
    timezone: normalizeTimezone(set.timezone),
    validFromUtc: normalizeTimestamp(set.validFromUtc),
    validUntilUtc: normalizeTimestamp(set.validUntilUtc),
    generationReason: sanitizeInterestingGenerationReason(set.generationReason),
    status: set.status === "failed" ? "failed" : "ready",
    catalogVersion: sanitizeStoredName(set.catalogVersion) || INTERESTING_TODAY_CATALOG_VERSION,
    createdAt: normalizeTimestamp(set.createdAt) || new Date().toISOString(),
  };
}

export function normalizeInterestingTodaySetItems(items, setId) {
  if (!Array.isArray(items)) {
    return [];
  }

  const seen = new Set();
  return items
    .map(item => normalizeInterestingTodaySetItem(item, setId))
    .filter(item => {
      const key = `${item?.recordType}:${item?.recordId}`;
      if (!item || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .sort((first, second) => first.recordType.localeCompare(second.recordType) || first.position - second.position);
}

export function selectInterestingTodayRecords({
  catalog,
  countryCode = INTERESTING_TODAY_DEFAULT_COUNTRY,
  language = INTERESTING_TODAY_LANGUAGE,
  localDate,
  eventsLimit = INTERESTING_TODAY_EVENTS_PER_DAY,
  peopleLimit = INTERESTING_TODAY_PEOPLE_PER_DAY,
} = {}) {
  const parsedDate = parseLocalDateParts(localDate);
  if (!parsedDate) {
    return createEmptySelection({ countryCode, language, localDate });
  }

  const normalizedCountry = normalizeInterestingCountryCode(countryCode) || INTERESTING_TODAY_DEFAULT_COUNTRY;
  const normalizedLanguage = language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : INTERESTING_TODAY_LANGUAGE;
  const eligible = normalizeInterestingTodayCatalog(catalog)
    .filter(record => isInterestingTodayEligibleForProduction(record))
    .filter(record => record.month === parsedDate.month && record.day === parsedDate.day && record.language === normalizedLanguage);
  const eventCandidates = sortInterestingRecords(eligible.filter(record => record.type === "event"), {
    countryCode: normalizedCountry,
    localDate,
  });
  const personCandidates = sortInterestingRecords(eligible.filter(record => record.type === "person"), {
    countryCode: normalizedCountry,
    localDate,
  });

  return {
    localDate: normalizeLocalDate(localDate),
    countryCode: normalizedCountry,
    language: normalizedLanguage,
    events: pickDiverseInterestingRecords(eventCandidates, eventsLimit),
    people: pickDiverseInterestingRecords(personCandidates, peopleLimit),
    availableEvents: eventCandidates.length,
    availablePeople: personCandidates.length,
  };
}

export function isInterestingTodayEligibleForProduction(record) {
  return isPlainObject(record)
    && RECORD_TYPES.has(record.type)
    && record.verificationStatus === INTERESTING_TODAY_VERIFICATION_STATUS
    && record.contentValidation === INTERESTING_TODAY_CONTENT_VALIDATION_PASSED
    && record.isActive === true
    && record.language === INTERESTING_TODAY_LANGUAGE
    && Array.isArray(record.sources)
    && record.sources.length > 0;
}

export function formatInterestingTodayRecordForApi(record, position = 1) {
  if (!record || !isInterestingTodayEligibleForProduction(record)) {
    return null;
  }

  const base = {
    id: record.id,
    type: record.type,
    position,
    month: record.month,
    day: record.day,
    year: record.type === "event" ? record.year : record.birthYear,
    title: record.type === "event" ? record.titleRu : record.nameRu,
    summary: record.summaryRu,
    description: record.descriptionRu,
    primaryCountryCode: record.primaryCountryCode,
    countryCodes: record.countryCodes,
    themeCodes: record.themeCodes,
    themeLabels: record.themeCodes.map(getInterestingThemeLabel).filter(Boolean),
    significance: record.significance,
    dateStatus: record.dateStatus,
    sources: record.sources.map(formatInterestingSourceForApi),
  };

  if (record.type === "person") {
    return {
      ...base,
      name: record.nameRu,
      birthYear: record.birthYear,
      deathYear: record.deathYear,
      lifeYears: formatLifeYears(record),
    };
  }

  return base;
}

export function formatInterestingTodayResponse({ set, events, people, preferences, availableEvents = 0, availablePeople = 0 }) {
  return {
    localDate: set.localDate,
    timezone: set.timezone,
    countryCode: set.countryCode,
    language: set.language,
    catalogVersion: set.catalogVersion,
    validFromUtc: set.validFromUtc,
    validUntilUtc: set.validUntilUtc,
    generationReason: set.generationReason,
    compact: {
      events: INTERESTING_TODAY_COMPACT_EVENTS,
      people: INTERESTING_TODAY_COMPACT_PEOPLE,
    },
    limits: {
      events: INTERESTING_TODAY_EVENTS_PER_DAY,
      people: INTERESTING_TODAY_PEOPLE_PER_DAY,
    },
    availableEvents,
    availablePeople,
    preferences: {
      countryCode: preferences.countryCode,
      language: preferences.language,
      showEvents: preferences.showEvents,
      showPeople: preferences.showPeople,
    },
    events: preferences.showEvents ? events : [],
    people: preferences.showPeople ? people : [],
  };
}

export function createInterestingTodayCatalogReport(records = DEFAULT_INTERESTING_TODAY_CATALOG, { checkedAt = new Date().toISOString() } = {}) {
  const rawRecords = Array.isArray(records) ? records : [];
  const normalized = normalizeInterestingTodayCatalog(rawRecords, { useDefaultWhenEmpty: false });
  const eligible = normalized.filter(isInterestingTodayEligibleForProduction);
  const eventCount = eligible.filter(record => record.type === "event").length;
  const personCount = eligible.filter(record => record.type === "person").length;
  const sourceCount = eligible.reduce((count, record) => count + record.sources.length, 0);
  const dateKeys = new Set(eligible.map(record => `${String(record.month).padStart(2, "0")}-${String(record.day).padStart(2, "0")}`));
  const fixtureIds = normalized.filter(record => record.id.startsWith("fixture-") || record.id.startsWith("test-")).map(record => record.id);
  const invalidCount = rawRecords.length - normalized.length;

  return {
    version: INTERESTING_TODAY_CATALOG_VERSION,
    checkedAt,
    rawRecordCount: rawRecords.length,
    normalizedRecordCount: normalized.length,
    eligibleRecordCount: eligible.length,
    eventCount,
    personCount,
    sourceCount,
    coveredDateCount: dateKeys.size,
    fixtureIds,
    invalidCount,
    ok: eligible.length > 0 && sourceCount >= eligible.length && fixtureIds.length === 0,
  };
}

export function createInterestingTodayDryRun(candidates = [], { target = "staging", checkedAt = new Date().toISOString(), createId = randomUUID } = {}) {
  const normalizedTarget = IMPORT_TARGETS.has(target) ? target : "staging";
  const normalizedCandidates = normalizeInterestingTodayCatalog(candidates, { useDefaultWhenEmpty: false });
  const validationResults = (Array.isArray(candidates) ? candidates : []).map((candidate, index) => {
    const normalized = normalizeInterestingTodayRecord(candidate);
    return {
      index,
      id: normalized?.id || sanitizeInterestingId(candidate?.id) || "",
      status: normalized ? (isInterestingTodayEligibleForProduction(normalized) ? "auto_verified" : "review_required") : "rejected",
      errors: normalized ? getInterestingRecordValidationErrors(normalized) : ["invalid_candidate"],
    };
  });
  const acceptedCount = validationResults.filter(result => result.status !== "rejected").length;

  return {
    batch: {
      id: sanitizeInterestingId(createId()) || `interesting-import-${Date.now()}`,
      target: normalizedTarget,
      status: normalizedTarget === "approved" && acceptedCount > 0 ? "ready_for_review" : "dry_run",
      candidateCount: Array.isArray(candidates) ? candidates.length : 0,
      acceptedCount,
      rejectedCount: validationResults.length - acceptedCount,
      checkedAt,
    },
    candidates: normalizedCandidates,
    validationResults,
  };
}

export function createInterestingTodaySetKey({ countryCode, language, localDate }) {
  return `${normalizeInterestingCountryCode(countryCode) || INTERESTING_TODAY_DEFAULT_COUNTRY}:${language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : INTERESTING_TODAY_LANGUAGE}:${normalizeLocalDate(localDate)}`;
}

export function normalizeInterestingCountryCode(value) {
  const code = String(value || "").trim().toUpperCase();
  if (code === INTERESTING_TODAY_WORLD_COUNTRY) {
    return code;
  }
  return COUNTRY_CODE_PATTERN.test(code) ? code : "";
}

export function normalizeLocalDate(value) {
  const date = String(value || "").trim();
  return /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : "";
}

export function normalizeTimezone(value) {
  const timezone = String(value || "UTC").trim();
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: timezone }).format(new Date());
    return timezone;
  } catch {
    return "UTC";
  }
}

function normalizeInterestingTodayRecord(record) {
  if (!isPlainObject(record)) {
    return null;
  }

  const type = RECORD_TYPES.has(record.type) ? record.type : "";
  const month = normalizeMonth(record.month);
  const day = normalizeDay(record.day, month);
  const primaryCountryCode = normalizeInterestingCountryCode(record.primaryCountryCode || record.countryCode) || INTERESTING_TODAY_WORLD_COUNTRY;
  const countryCodes = normalizeCountryCodes(record.countryCodes || [primaryCountryCode]);
  const themeCodes = normalizeThemeCodes(record.themeCodes || record.themes);
  const sources = normalizeInterestingSources(record.sources);
  const dateStatus = DATE_STATUSES.has(record.dateStatus) ? record.dateStatus : "exact";
  const verificationStatus = VERIFICATION_STATUSES.has(record.verificationStatus) ? record.verificationStatus : INTERESTING_TODAY_VERIFICATION_STATUS;
  const contentValidation = CONTENT_VALIDATION_STATUSES.has(record.contentValidation) ? record.contentValidation : INTERESTING_TODAY_CONTENT_VALIDATION_PASSED;
  const baseTitle = type === "event" ? sanitizeStoredText(record.titleRu || record.title, 180) : sanitizeStoredText(record.nameRu || record.name, 160);
  const summaryRu = sanitizeStoredText(record.summaryRu || record.summary, 260);
  let descriptionRu = sanitizeStoredText(record.descriptionRu || record.description, 1200);
  descriptionRu = normalizeInterestingDescription({
    type,
    title: baseTitle,
    summaryRu,
    descriptionRu,
  });

  if (!type || !month || !day || !baseTitle || !summaryRu || !descriptionRu || !themeCodes.length || !sources.length) {
    return null;
  }

  const normalizedHash = createInterestingHash(`${type}:${month}:${day}:${type === "event" ? normalizeYear(record.year) : normalizeYear(record.birthYear)}:${normalizeComparableText(baseTitle)}`);
  const id = sanitizeInterestingId(record.id) || `interesting-${type}-${normalizedHash.slice(0, 16)}`;
  const common = {
    id,
    type,
    month,
    day,
    primaryCountryCode,
    countryCodes,
    themeCodes,
    language: record.language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : INTERESTING_TODAY_LANGUAGE,
    summaryRu,
    descriptionRu,
    significance: normalizeSignificance(record.significance),
    dateStatus,
    verificationStatus,
    contentValidation,
    isActive: record.isActive !== false,
    sources,
    normalizedHash,
    verifiedBy: sanitizeStoredName(record.verifiedBy) || "Focus editorial seed",
    verifiedAt: normalizeTimestamp(record.verifiedAt) || "2026-08-05T00:00:00.000Z",
    createdAt: normalizeTimestamp(record.createdAt) || "2026-08-05T00:00:00.000Z",
    updatedAt: normalizeTimestamp(record.updatedAt) || normalizeTimestamp(record.createdAt) || "2026-08-05T00:00:00.000Z",
  };

  if (type === "event") {
    const year = normalizeYear(record.year);
    if (year === null) {
      return null;
    }

    return {
      ...common,
      titleRu: baseTitle,
      year,
    };
  }

  const birthYear = normalizeYear(record.birthYear ?? record.year);
  if (birthYear === null) {
    return null;
  }

  return {
    ...common,
    nameRu: baseTitle,
    birthYear,
    deathYear: normalizeYear(record.deathYear),
  };
}

function normalizeInterestingTodaySetItem(item, setId) {
  if (!isPlainObject(item)) {
    return null;
  }

  const recordId = sanitizeInterestingId(item.recordId);
  const recordType = RECORD_TYPES.has(item.recordType) ? item.recordType : "";
  const position = Math.floor(Number(item.position));
  const maxPosition = recordType === "event" ? INTERESTING_TODAY_EVENTS_PER_DAY : INTERESTING_TODAY_PEOPLE_PER_DAY;
  if (!recordId || !recordType || position < 1 || position > maxPosition) {
    return null;
  }

  return {
    setId: sanitizeInterestingId(item.setId) || setId,
    recordId,
    recordType,
    position,
    createdAt: normalizeTimestamp(item.createdAt) || new Date().toISOString(),
  };
}

function sortInterestingRecords(records, { countryCode, localDate }) {
  return [...records].sort((first, second) => {
    const scoreDiff = getInterestingRecordScore(second, countryCode) - getInterestingRecordScore(first, countryCode);
    if (scoreDiff !== 0) return scoreDiff;

    const firstHash = createInterestingHash(`${localDate}:${countryCode}:${first.type}:${first.id}`);
    const secondHash = createInterestingHash(`${localDate}:${countryCode}:${second.type}:${second.id}`);
    return firstHash.localeCompare(secondHash);
  });
}

function getInterestingRecordScore(record, countryCode) {
  let score = record.significance;
  if (record.primaryCountryCode === countryCode) {
    score += 48;
  } else if (record.countryCodes.includes(countryCode)) {
    score += 40;
  } else if (record.countryCodes.includes(INTERESTING_TODAY_WORLD_COUNTRY) || record.primaryCountryCode === INTERESTING_TODAY_WORLD_COUNTRY) {
    score += 0;
  }
  if (hasGeneratedInterestingText(record)) {
    score -= 26;
  }
  if (hasOnlyWeakInterestingSources(record)) {
    score -= 60;
  }
  return score;
}

function normalizeInterestingDescription({ type, title, summaryRu, descriptionRu }) {
  if (!hasGeneratedInterestingTextValue(descriptionRu)) {
    return descriptionRu;
  }

  const summary = ensureInterestingSentence(summaryRu);
  const titleSentence = ensureInterestingSentence(title);
  const contextSentence = type === "person"
    ? "\u041f\u043e\u0434\u0431\u043e\u0440\u043a\u0430 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u044d\u0442\u0443 \u0434\u0430\u0442\u0443 \u043a\u0430\u043a \u0434\u0435\u043d\u044c \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0437\u0430\u043c\u0435\u0442\u043d\u043e\u0439 \u0444\u0438\u0433\u0443\u0440\u044b; \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043d\u0443\u0436\u0435\u043d \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0434\u0430\u0442\u044b \u0438 \u0431\u0438\u043e\u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430."
    : "\u041f\u043e\u0434\u0431\u043e\u0440\u043a\u0430 \u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u044d\u0442\u0443 \u0434\u0430\u0442\u0443 \u0432 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u0435 \u043a\u0430\u043a \u0437\u0430\u043c\u0435\u0442\u043d\u044b\u0439 \u0438\u0441\u0442\u043e\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u043e\u0440\u0438\u0435\u043d\u0442\u0438\u0440; \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043d\u0443\u0436\u0435\u043d \u0434\u043b\u044f \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u0434\u0430\u0442\u044b \u0438 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430.";

  const normalized = type === "person"
    ? `${titleSentence} ${summary} ${contextSentence}`
    : `${summary || titleSentence} ${contextSentence}`;

  return sanitizeStoredText(normalized, 1200);
}

function ensureInterestingSentence(value) {
  const text = sanitizeStoredText(value, 400);
  if (!text) return "";
  return /[.!?\u2026]$/.test(text) ? text : `${text}.`;
}

function hasGeneratedInterestingText(record) {
  return hasGeneratedInterestingTextValue(`${record.summaryRu || ""} ${record.descriptionRu || ""}`);
}

function hasGeneratedInterestingTextValue(value) {
  const text = String(value || "");
  return GENERATED_TEXT_MARKERS.some(marker => text.includes(marker));
}

function hasOnlyWeakInterestingSources(record) {
  return Array.isArray(record.sources) &&
    record.sources.length > 0 &&
    record.sources.every(isWeakInterestingSource);
}

function isWeakInterestingSource(source) {
  if (!isPlainObject(source)) {
    return true;
  }

  let pathname = "";
  try {
    pathname = decodeURIComponent(new URL(source.url).pathname);
  } catch {
    return true;
  }

  const title = String(source.titleRu || "").trim();
  return /wikipedia\.org$/i.test(new URL(source.url).hostname) &&
    (WIKIPEDIA_YEAR_PAGE_TITLE_PATTERN.test(title) || /^\/wiki\/\d{1,4}_\u0433\u043e\u0434$/iu.test(pathname));
}

function pickDiverseInterestingRecords(records, limit) {
  const selected = [];
  const themeCounts = new Map();
  const maxPerTheme = 2;

  records.forEach(record => {
    if (selected.length >= limit) return;
    const primaryTheme = record.themeCodes[0] || "other";
    if ((themeCounts.get(primaryTheme) || 0) >= maxPerTheme) return;
    selected.push(record);
    themeCounts.set(primaryTheme, (themeCounts.get(primaryTheme) || 0) + 1);
  });

  records.forEach(record => {
    if (selected.length >= limit) return;
    if (selected.some(item => item.id === record.id)) return;
    selected.push(record);
  });

  return selected.slice(0, limit);
}

function createEmptySelection({ countryCode, language, localDate }) {
  return {
    localDate: normalizeLocalDate(localDate),
    countryCode: normalizeInterestingCountryCode(countryCode) || INTERESTING_TODAY_DEFAULT_COUNTRY,
    language: language === INTERESTING_TODAY_LANGUAGE ? INTERESTING_TODAY_LANGUAGE : INTERESTING_TODAY_LANGUAGE,
    events: [],
    people: [],
    availableEvents: 0,
    availablePeople: 0,
  };
}

function getInterestingRecordValidationErrors(record) {
  const errors = [];
  if (!record.sources.length) errors.push("source_required");
  if (!record.themeCodes.length) errors.push("theme_required");
  if (record.contentValidation !== INTERESTING_TODAY_CONTENT_VALIDATION_PASSED) errors.push("content_not_passed");
  if (record.verificationStatus !== INTERESTING_TODAY_VERIFICATION_STATUS) errors.push("manual_verification_required");
  if (!record.isActive) errors.push("inactive_record");
  return errors;
}

function normalizeInterestingSources(sources) {
  const seen = new Set();
  return Array.isArray(sources)
    ? sources.map(normalizeInterestingSource).filter(source => {
        if (!source || seen.has(source.id)) return false;
        seen.add(source.id);
        return true;
      }).slice(0, 5)
    : [];
}

function normalizeInterestingSource(source) {
  if (!isPlainObject(source)) {
    return null;
  }

  const titleRu = sanitizeStoredText(source.titleRu || source.title, 180);
  const publisherRu = sanitizeStoredText(source.publisherRu || source.publisher, 160);
  const url = normalizeUrl(source.url);
  if (!titleRu || !publisherRu || !url) {
    return null;
  }

  const id = sanitizeInterestingId(source.id) || `source-${createInterestingHash(`${titleRu}:${url}`).slice(0, 14)}`;
  const sourceType = SOURCE_TYPE_PATTERN.test(String(source.sourceType || "")) ? source.sourceType : "reference";
  return {
    id,
    titleRu,
    publisherRu,
    url,
    sourceType,
  };
}

function formatInterestingSourceForApi(source) {
  return {
    id: source.id,
    title: source.titleRu,
    publisher: source.publisherRu,
    url: source.url,
    sourceType: source.sourceType,
  };
}

function normalizeMonth(value) {
  const month = Math.floor(Number(value));
  return month >= 1 && month <= 12 ? month : 0;
}

function normalizeDay(value, month) {
  const day = Math.floor(Number(value));
  const maxDay = [31, isLeapCatalogMonth(month) ? 29 : 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1] || 0;
  return day >= 1 && day <= maxDay ? day : 0;
}

function isLeapCatalogMonth(month) {
  return month === 2;
}

function normalizeYear(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const year = Math.floor(Number(value));
  return Number.isFinite(year) && year >= -4000 && year <= 3000 ? year : null;
}

function normalizeSignificance(value) {
  const significance = Math.floor(Number(value));
  return Number.isFinite(significance) ? Math.max(1, Math.min(100, significance)) : 50;
}

function normalizeCountryCodes(value) {
  const seen = new Set();
  const codes = Array.isArray(value) ? value : [];
  return codes
    .map(normalizeInterestingCountryCode)
    .filter(code => code && !seen.has(code) && seen.add(code))
    .slice(0, 8);
}

function normalizeThemeCodes(value) {
  const seen = new Set();
  const codes = Array.isArray(value) ? value : [];
  return codes
    .map(code => String(code || "").trim())
    .filter(code => THEME_CODE_PATTERN.test(code) && !seen.has(code) && seen.add(code))
    .slice(0, 6);
}

function getInterestingThemeLabel(code) {
  return INTERESTING_TODAY_THEMES.find(theme => theme.code === code)?.titleRu || "";
}

function formatLifeYears(record) {
  const birth = record.birthYear === null ? "" : String(record.birthYear);
  const death = record.deathYear === null ? "" : String(record.deathYear);
  return death ? `${birth}-${death}` : `${birth}`;
}

function parseLocalDateParts(value) {
  const normalized = normalizeLocalDate(value);
  if (!normalized) {
    return null;
  }

  const [, month, day] = normalized.split("-").map(Number);
  return { month, day };
}

function sanitizeInterestingGenerationReason(value) {
  return [
    INTERESTING_TODAY_GENERATION_REASON,
    INTERESTING_TODAY_FALLBACK_REASON,
    "admin_rebuild",
  ].includes(value) ? value : INTERESTING_TODAY_GENERATION_REASON;
}

function sanitizeInterestingId(value) {
  const id = String(value || "").trim();
  return ID_PATTERN.test(id) ? id : "";
}

function sanitizeStoredName(value) {
  return typeof value === "string" ? value.replace(/\s+/g, " ").trim().slice(0, 160) : "";
}

function sanitizeStoredText(value, maxLength = 500) {
  return typeof value === "string" ? value.replace(/\s+/g, " ").trim().slice(0, maxLength) : "";
}

function normalizeTimestamp(value) {
  const timestamp = String(value || "").trim();
  if (!timestamp) return null;

  const date = new Date(timestamp);
  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

function normalizeUrl(value) {
  try {
    const url = new URL(String(value || "").trim());
    return url.href;
  } catch {
    return "";
  }
}

function normalizeComparableText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[«»"“”„]/g, "")
    .replace(/[.,!?;:—–-]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function createInterestingHash(value) {
  return createHash("sha256").update(String(value || "")).digest("hex");
}

function isPlainObject(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}
